      bal += `M${f(x - 3.4)} 718C${f(x - 5.6)} 710 ${f(x - 1.6)} 706 ${f(x - 2)} 700C${f(x - 5.6)} 694 ${f(x - 4.6)} 684 ${f(x - 2.4)} 680L${f(x + 2.4)} 680C${f(x + 4.6)} 684 ${f(x + 5.6)} 694 ${f(x + 2)} 700C${f(x + 1.6)} 706 ${f(x + 5.6)} 710 ${f(x + 3.4)} 718Z`;
