    // flowers
    const daisy = (x, y, r) => { const [p, c] = flower5(x, y, r, Rn() * 70); return [O(p, M.Paper, 1.2), O(c, M.Yellow, 1)]; };
    const cup = (x, y, r) => { const [p, c] = flower5(x, y, r, Rn() * 70); return [O(p, M.Yellow, 1.2), O(c, M.Orange, 1)]; };
    const thrift = (x, y, hh) => S(`M${x} ${y}q2 ${-hh / 2} 0 ${-hh}`, M.GrassLo, 2.4) + O(blob(x, y - hh, 7.4), M.Pink, 1.4) + F(circ(x - 2, y - hh - 2, 2.4), M.PinkHi);
    const poppy = (x, y, r) => S(`M${x} ${y + 30}q-4 -15 0 -30`, M.GrassLo, 2.2) + O(`M${f(x)} ${f(y + 2)}C${f(x - r * 1.6)} ${f(y + 2)} ${f(x - r * 1.6)} ${f(y - r * 1.4)} ${f(x - r * 0.8)} ${f(y - r * 1.6)}C${f(x - r * 0.4)} ${f(y - r)} ${f(x + r * 0.4)} ${f(y - r)} ${f(x + r * 0.8)} ${f(y - r * 1.6)}C${f(x + r * 1.6)} ${f(y - r * 1.4)} ${f(x + r * 1.6)} ${f(y + 2)} ${f(x)} ${f(y + 2)}Z`, M.Red, 1.3) + F(circ(x, y - 2, r * 0.3), M.Dark);
    const dand = (x, y, r) => { let rr = ''; for (let i = 0; i < 14; i++) { const p1 = add([x, y], rot([r, 0], i * 25.7)); rr += `M${f(x)} ${f(y)}L${f(p1[0])} ${f(p1[1])}`; } return S(`M${x} ${y + 34}q-2 -16 0 -34`, M.GrassLo, 1.8) + F(circ(x, y, r), M.Paper, { opacity: 0.55 }) + S(rr, M.Paper, 0.8) + S(circ(x, y, r), LC, 0.5, { opacity: 0.5 }) + F(circ(x, y, 1.6), M.WoodHi); };
